CREATE OR REPLACE FUNCTION public.create_contract_completion_invoice(p_work_order uuid,p_customer jsonb,p_lines jsonb,p_net numeric,p_vat numeric,p_total numeric,p_vat_rate numeric,p_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.contract_billing_queue; result uuid; issue date=(now() AT TIME ZONE 'Europe/Brussels')::date; n integer; prefix text; BEGIN SELECT * INTO q FROM public.contract_billing_queue WHERE work_order_id=p_work_order FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No queued completion'; END IF; SELECT id INTO result FROM public.invoices WHERE work_order_id=p_work_order AND contract_id IS NOT NULL AND kind='factuur'; IF result IS NULL THEN UPDATE public.settings SET next_invoice_number=next_invoice_number+1 WHERE id=1 RETURNING next_invoice_number-1,invoice_prefix INTO n,prefix; INSERT INTO public.invoices(number,work_order_id,contract_id,contract_reference,issue_date,due_date,customer,lines,vat_rate,net,vat,total,paid_amount) VALUES(prefix||n::text,p_work_order,q.contract_id,p_reference,issue,issue+(SELECT payment_days FROM public.settings WHERE id=1),p_customer,p_lines,p_vat_rate,p_net,p_vat,p_total,0) RETURNING id INTO result; END IF; UPDATE public.contract_billing_queue SET invoice_id=result,status='created',updated_at=now() WHERE work_order_id=p_work_order; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_contract_completion_invoice(uuid,jsonb,jsonb,numeric,numeric,numeric,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_contract_completion_invoice(uuid,jsonb,jsonb,numeric,numeric,numeric,numeric,text) TO service_role;